vismEcanTail = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 3, 5, 1, 1, 1, 5), Integer32().subtype(subtypeSpec=ValueRangeConstraint(24, 128)).clone(32)).setUnits('milliseconds').setMaxAccess("readwrite")
