vismEcanREC = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 3, 5, 1, 1, 1, 6), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))).clone(namedValues=NamedValues(("cancelOnly", 1), ("suppressResidual", 2), ("reserved", 3), ("comfortNoise", 4))).clone('suppressResidual')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: vismEcanREC.setStatus('current')
if mibBuilder.loadTexts: vismEcanREC.setDescription("Residual Echo Control (REC) instructs the canceler\n         how to treat echo remaining after cancellation.\n\n         'cancelOnly'      : REC is disabled.\n         'suppressResidual': The residual echo is replaced\n                             with silence.\n         'comfortNoise'    : Noise is injected in place of\n                             residual echo at the same level\n                             as the ambient noise at the near\n                             end.\n         'reserved'        : Results in BadValue error.\n        ")
