vismDsx1MidcallTpart = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 3, 5, 1, 1, 1, 24), Integer32().subtype(subtypeSpec=ValueRangeConstraint(10, 10000)).clone(16)).setUnits('seconds').setMaxAccess("readwrite")
