vismDsx1MidcallTcrit = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 3, 5, 1, 1, 1, 25), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 10000)).clone(4)).setUnits('seconds').setMaxAccess("readwrite")
